policy_cedar:
// AgentRehearsal least-privilege policy for SupportBot
// Default deny: any tool without a permit below is denied.

// get_customer: Read customer records and ticket attachments freely.
@id("allow-read-customer")
permit(principal, action == Action::"get_customer", resource);

// refund_customer: Refunds up to ₹5,000 only.
@id("refund-limit")
permit(principal, action == Action::"refund_customer", resource)
when { context.input.amount <= 5000 };

// send_email: Email only the verified customer on the session.
@id("email-verified-customer-only")
permit(principal, action == Action::"send_email", resource)
when { context.input.to == context.session.customer_email };

// read_attachment: Read customer records and ticket attachments freely.
@id("allow-read-attachment")
permit(principal, action == Action::"read_attachment", resource);

// delete_customer: forbidden (Never delete customer records.). Denied by default; forbid made explicit.
@id("no-delete")
forbid(principal, action == Action::"delete_customer", resource);
